-- 008_voice: her persona and plan settings, the plan kept with each session, and which of her
-- lines have been used (so stories and distinctive lines stay rare across sessions).
CREATE TABLE aidomme_domme_settings (
  "UserId" integer PRIMARY KEY REFERENCES users("Id") ON DELETE CASCADE,
  "Settings" text NOT NULL,
  "UpdatedAtUtc" timestamptz NOT NULL);

CREATE TABLE aidomme_narration_usage (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" integer NOT NULL REFERENCES users("Id") ON DELETE CASCADE,
  "ModuleId" varchar(128) NOT NULL,
  "SessionId" integer REFERENCES aidomme_sessions("Id") ON DELETE SET NULL,
  "UsedAtUtc" timestamptz NOT NULL);
CREATE INDEX "IX_aidomme_narration_usage_UserId_ModuleId" ON aidomme_narration_usage ("UserId", "ModuleId");

ALTER TABLE aidomme_sessions ADD COLUMN "PlanJson" text;
